1	#!/usr/bin/env node
2	/**
3	 * Differential harness: run the reference executable and the Node port with the
4	 * same arguments and compare stdout and exit status byte for byte.
5	 */
6	import { spawnSync } from 'node:child_process';
7	
8	const REF = '/workspace/dataset/test20_executable';
9	const JS = ['/output/test20.mjs'];
10	
11	export function runCase(argv, timeout = 20000) {
12	  const ref = spawnSync(REF, argv, { encoding: 'latin1', timeout, maxBuffer: 1 << 28 });
13	  const js = spawnSync('node', [...JS, ...argv], { encoding: 'latin1', timeout, maxBuffer: 1 << 28 });
14	  const norm = (r) => ({
15	    out: r.stdout === null ? '' : r.stdout,
16	    err: r.stderr === null ? '' : r.stderr,
17	    code: r.status === null ? `signal:${r.signal}` : r.status,
18	  });
19	  const a = norm(ref);
20	  const b = norm(js);
21	  return { ok: a.out === b.out && a.code === b.code, ref: a, js: b, argv };
22	}
23	
24	export function describe(argv) {
25	  return argv.map((x) => JSON.stringify(x)).join(' ');
26	}
27	
28	export function report(results, { showStderr = false } = {}) {
29	  let pass = 0;
30	  const failures = [];
31	  for (const r of results) {
32	    if (r.ok) pass += 1;
33	    else failures.push(r);
34	  }
35	  console.log(`${pass}/${results.length} passed`);
36	  for (const f of failures.slice(0, 12)) {
37	    console.log('\n--- FAIL: ' + describe(f.argv));
38	    console.log(`exit: ref=${f.ref.code} js=${f.js.code}`);
39	    const refLines = f.ref.out.split('\n');
40	    const jsLines = f.js.out.split('\n');
41	    for (let i = 0; i < Math.max(refLines.length, jsLines.length); i += 1) {
42	      if (refLines[i] !== jsLines[i]) {
43	        console.log(`  line ${i + 1}: ref=${JSON.stringify(refLines[i])} js=${JSON.stringify(jsLines[i])}`);
44	      }
45	    }
46	    if (showStderr) {
47	      console.log('  ref stderr: ' + JSON.stringify(f.ref.err));
48	      console.log('  js  stderr: ' + JSON.stringify(f.js.err));
49	    }
50	  }
51	  return failures.length === 0;
52	}
