// Dash-leading / argparse-shaped value fuzzer + int-parse fuzzer.
// usage: node randdiff-worker3.mjs <seed> <count> <outfile>
import { runCase, describe } from '/tmp/harness.mjs';
import { writeFileSync } from 'node:fs';

const seed = Number(process.argv[2]);
const count = Number(process.argv[3]);
const outfile = process.argv[4];

let s = seed >>> 0;
function rnd() {
  s = (s + 0x6d2b79f5) >>> 0;
  let t = s;
  t = Math.imul(t ^ (t >>> 15), t | 1);
  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
}
const ri = (n) => Math.floor(rnd() * n);
const pick = (a) => a[ri(a.length)];

const B58 = '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';
const PRINT = (() => { let x = ''; for (let c = 0x20; c < 0x7f; c += 1) x += String.fromCharCode(c); return x; })();
const SECOND = ['=', '-', 'h', 'a', 'b', 'g', '9', '1', '.', ' ', '_', 'x', '+', '\t', '', 'e'];
const TAILS = ['', 'x', ' x', 'x y', '=z', ' ', '  ', '=', 'a b c', '\ty', '1', '5.5', 'help', '-'];

function randStr(len, pool) { let o = ''; for (let i = 0; i < len; i += 1) o += pool[ri(pool.length)]; return o; }

function dashy() {
  const dashes = '-'.repeat(1 + ri(3));
  return dashes + pick(SECOND) + pick(TAILS) + (ri(3) === 0 ? randStr(ri(6), PRINT) : '');
}
function strArg() {
  switch (ri(8)) {
    case 0: return dashy();
    case 1: return dashy();
    case 2: return dashy();
    case 3: return '-' + randStr(1 + ri(6), PRINT + ' ');
    case 4: return randStr(1 + ri(20), PRINT);
    case 5: return '';
    case 6: return '=' + randStr(ri(5), PRINT);
    default: return randStr(1 + ri(10), PRINT + ' \t');
  }
}
function b58Arg() {
  switch (ri(6)) {
    case 0: return randStr(1 + ri(30), B58);
    case 1: return '1'.repeat(1 + ri(8)) + randStr(ri(10), B58);
    case 2: return randStr(1 + ri(10), B58) + pick(['', ' ', '\n', '\t', ' ']);
    case 3: return dashy();
    case 4: return '';
    default: return randStr(1 + ri(60), B58);
  }
}
const WS = ['\t', '\n', '\v', '\f', '\r', '\x1c', '\x1d', '\x1e', '\x1f', ' ', ' ', ' ', ' ', ' ', ' ', '　', ' ', ' ', ' ', '', '​', '᠎', ' '];
const DIGITSETS = ['0123456789', '٠١٢٣٤٥٦٧٨٩', '０１２３４５６７８９', '०१२३४५६७८९', '๐๑๒๓๔๕๖๗๘๙', '𝟎𝟏𝟐𝟑𝟒𝟓𝟔𝟕𝟖𝟗', '০১২৩৪৫৬৭৮৯'];
function intArg() {
  switch (ri(16)) {
    case 0: return pick(WS) + String(ri(100000));
    case 1: return String(ri(100000)) + pick(WS);
    case 2: return pick(WS) + String(ri(100000)) + pick(WS);
    case 3: { const ds = pick(DIGITSETS); let o = ''; const n = 1 + ri(5); for (let i = 0; i < n; i += 1) o += ds[ri(10)]; return o; }
    case 4: return '+' + String(ri(100000));
    case 5: return '-0';
    case 6: return '0'.repeat(1 + ri(8));
    case 7: { const a = String(ri(1e8)); return a.split('').join(ri(2) ? '_' : ''); }
    case 8: return String(ri(1e6)) + '_';
    case 9: return '_' + String(ri(1e6));
    case 10: return String(2n ** BigInt(1 + ri(160)));
    case 11: return String(58n ** BigInt(1 + ri(40)) - BigInt(ri(2)));
    case 12: return String(256n ** BigInt(1 + ri(20)) - BigInt(ri(2)));
    case 13: { let d = String(1 + ri(9)); const n = ri(50); for (let i = 0; i < n; i += 1) d += ri(10); return d; }
    case 14: return pick(['0', '1', '57', '58', '59', '3363', '3364', '255', '256', '65535', '65536']);
    default: return String(ri(1e9));
  }
}

const failures = [];
let ran = 0;
for (let n = 0; n < count; n += 1) {
  const argv = ['--a', strArg(), '--b', b58Arg(), '--c', strArg(), '--d', strArg(), '--e', b58Arg(), '--f', intArg(), '--g', intArg()];
  const r = runCase(argv, 25000);
  ran += 1;
  if (!r.ok) {
    const r2 = runCase(argv, 60000);
    if (!r2.ok) { const r3 = runCase(argv, 60000); if (!r3.ok) failures.push({ argv, ref: r3.ref, js: r3.js }); }
  }
}
writeFileSync(outfile, JSON.stringify({ seed, ran, failures }, null, 1));
console.log(`seed=${seed} ran=${ran} failures=${failures.length}`);
for (const f of failures) console.log('FAIL ' + describe(f.argv).slice(0, 300));

