console.log('ran:', total, 'failures:', all.length);
for (const f of all) {
  const rl = f.ref.out.split('\n'); const jl = f.js.out.split('\n');
  const bad = []; for (let i = 0; i < Math.max(rl.length, jl.length); i += 1) if (rl[i] !== jl[i]) bad.push(i + 1);
