    console.log(`  L${i} ref=${JSON.stringify(rl[i - 1]).slice(0, 250)}`);
    console.log(`  L${i} js =${JSON.stringify(jl[i - 1]).slice(0, 250)}`);
  }
  console.log('  ref err:', JSON.stringify(f.ref.err.slice(0, 220)));
  console.log('  js  err:', JSON.stringify(f.js.err.slice(0, 220)));
}
